import fs from 'fs';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import path from 'path';
import { isEphemeralNpxInstall } from './mcpRegistration';
import { runNpm } from './npmCommand';
import { RIVET_VERSION } from '../config/telemetry';
import { errorMessage } from '../utils/errorMessage';
import {
  spawnProcessSync,
  type ProcessCommand,
} from '../services/packageManagerProcess';

export type BootstrapExec = (
  command: ProcessCommand,
  options: { env: NodeJS.ProcessEnv; stdio: 'inherit' | 'pipe' },
) => Promise<{ status: number | null; stdout?: string }>;

export type BootstrapResult =
  | { action: 'not_needed' }
  | { action: 'reexeced'; exitCode: number }
  | { action: 'failed'; reason: string };

const defaultExec: BootstrapExec = async (command, { env, stdio }) => {
  if ('packageManager' in command && command.packageManager === 'npm') {
    const result = await runNpm({
      args: command.args,
      env: subprocessEnvironment('packageManager', env),
      stdio,
    });
    if (result.error) throw result.error;
    return { status: result.status, stdout: result.stdout };
  }
  const result = spawnProcessSync(command, {
    stdio,
    env: subprocessEnvironment(
      'packageManager' in command ? 'packageManager' : 'rivetRuntime',
      env,
    ),
  });
  if (result.error) throw result.error;
  return { status: result.status, stdout: result.stdout ?? undefined };
};

export const bootstrapGlobalInstall = async (
  installArgs: string[],
  options?: {
    exec?: BootstrapExec;
    binPath?: string;
    env?: NodeJS.ProcessEnv;
    version?: string;
  },
): Promise<BootstrapResult> => {
  const exec = options?.exec ?? defaultExec;
  const env = options?.env ?? process.env;
  if (!isEphemeralNpxInstall(options?.binPath)) {
    return { action: 'not_needed' };
  }

  const spec =
    env.RIVET_GLOBAL_INSTALL_SPEC ??
    `rivet-design@${options?.version ?? RIVET_VERSION}`;
  console.log(
    `Rivet is running from npx's temporary cache — installing ${spec} globally first so ` +
      'MCP registrations and `rivet` commands keep working...\n',
  );
  try {
    const installResult = await exec(
      { packageManager: 'npm', args: ['install', '-g', spec] },
      { env, stdio: 'inherit' },
    );
    if (installResult.status !== 0) {
      return {
        action: 'failed',
        reason: `npm install -g exited ${installResult.status}`,
      };
    }
    const rootResult = await exec(
      { packageManager: 'npm', args: ['root', '-g'] },
      { env, stdio: 'pipe' },
    );
    const globalRoot = String(rootResult.stdout ?? '').trim();
    const globalBin = path.join(globalRoot, 'rivet-design', 'bin', 'rivet.js');
    if (!globalRoot || !fs.existsSync(globalBin)) {
      return {
        action: 'failed',
        reason: `global install not found at ${globalBin || 'npm root -g'}`,
      };
    }
    const rerun = await exec(
      {
        executable: process.execPath,
        args: [globalBin, 'install', ...installArgs],
      },
      { env, stdio: 'inherit' },
    );
    return { action: 'reexeced', exitCode: rerun.status ?? 0 };
  } catch (error) {
    return {
      action: 'failed',
      reason: errorMessage(error),
    };
  }
};

export const bootstrapFailureAdvisory = (reason: string): string =>
  `Warning: could not install Rivet globally (${reason}).\n` +
  'Continuing with the CLI setup, but MCP registrations are skipped: a\n' +
  "registration pointing into npx's temporary cache would break on the next\n" +
  'cache prune. To finish setup, run:\n\n' +
  '  npm install -g rivet-design && rivet install\n';
